inline const char* Ni(uint32_t i) { return kNames + i; }

// binary search helpers
inline int ColFind(uint64_t v) {
    int lo = 0, hi = (int)(sizeof(kCols)/sizeof(kCols[0])) - 1;
    while (lo <= hi) { int m = (lo+hi)>>1;
        if (kCols[m].va == v) return m;
        if (kCols[m].va < v) lo = m+1; else hi = m-1; }
    return -1;
}
inline int TiFind(uint64_t v) {
    int lo = 0, hi = (int)(sizeof(kTiSites)/sizeof(kTiSites[0])) - 1;
    while (lo <= hi) { int m = (lo+hi)>>1;
        if (kTiSites[m].va == v) return m;
        if (kTiSites[m].va < v) lo = m+1; else hi = m-1; }
    return -1;
}

